/**
 * @ohos/dsh-tool-user-profile — cross-session notes about the user, kept as a
 * plain Markdown file the model appends to and reads back.
 *
 * The problem this solves: dsh has no user-profile / behavioral-memory seam.
 * A session remembers only its own transcript, and the client keeps the last
 * 200 messages of it; start a new conversation and the model knows nothing
 * about the person it is talking to. The one cross-session channel that DOES
 * exist is `dsh-agent-instructions`, which loads `AGENTS.md`-compatible files
 * into durable context before the first request of every session.
 *
 * So this tool does not invent a memory store. It writes one instruction file:
 *
 *   <DSH_HOME>/AGENTS.md      ← user-global chain, loaded into every session
 *     └ managed block         ← the only range this tool writes
 *
 * Everything outside the block is the user's own prose and is never touched.
 * That boundary is the whole design: the model can be wrong about you, and you
 * can delete or edit its claims without losing your own instructions.
 *
 * Why timestamps and why one fact per line: a profile that only says "prefers
 * concise answers" cannot be audited or superseded six months later. Each line
 * carries the date it was learned, so a stale claim is visibly stale, and a
 * contradicted claim can be `replace`d rather than silently coexisting with its
 * opposite. This is the drift problem stated in the design discussion, handled
 * by making the record self-dating instead of pretending a profile is timeless.
 *
 * Verified mechanics (not inferred from README):
 *   - `$DSH_HOME/AGENTS.md` and `$DSH_HOME/agents-global/AGENTS.md` are both
 *     read as the user-global chain (`USER_GLOBAL_DIRECTORIES`);
 *   - the project chain walks `findProjectRoot(cwd)` down to cwd, so a bare
 *     `AGENTS.md` beside the workspace is loaded WITHOUT a `.git` directory;
 *   - `AGENTS.local.md` is an additive overlay, so the profile could live there
 *     instead — this tool chooses the harness home so one file serves every
 *     project on the device;
 *   - the rendered text is a `<system-reminder>` block carrying the file body
 *     verbatim, which is why the managed markers survive as markers.
 *
 * Reads and writes go through `node:fs/promises` rather than `ctx.fs`: the
 * target lives in the harness home, which is outside the session workspace, and
 * `ctx.fs` is fenced by the sandbox mode. Writing there through the sandbox would
 * be denied in `workspace-write`, and this file is not user content — it is
 * harness configuration, the same category as the profile templates that
 * bootstrap.cjs writes beside it.
 */
import z from "@deepseek-ai/schemastery";
import { defineTool } from "@deepseek-ai/dsh-tools";
import { HarnessError } from "@deepseek-ai/dsh-llm";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { rename, unlink } from "node:fs/promises";
import { dirname, isAbsolute, join } from "node:path";
import { randomUUID } from "node:crypto";

const name = "tool-user-profile";
const inject = ["tools"];

/**
 * The managed range. HTML comments so they are invisible when the file is
 * rendered, and distinctive enough that a `grep BEGIN_MARKER` finds them.
 */
const BEGIN_MARKER = "<!-- dsh:user-profile:begin -->";
const END_MARKER = "<!-- dsh:user-profile:end -->";

/** Hard cap on remembered facts. Oldest entries are dropped past this. */
const MAX_FACTS = 80;
/** One fact's text is capped so a runaway model cannot fill the context budget. */
const MAX_FACT_TEXT = 400;
/**
 * Budget guard. `dsh-agent-instructions` caps each chain at 64KiB by default,
 * and the user-global chain shares that budget with the user's own prose, so
 * the managed block stops growing well before the cap and says so.
 */
const MAX_BLOCK_BYTES = 12 * 1024;

const Config = z.object({
	fileName: z
		.string()
		.description(
			"File to keep the profile in, relative to the harness home. Defaults to AGENTS.md, the user-global instruction chain every session loads.",
		)
		.default("AGENTS.md"),
	maxFacts: z
		.number()
		.step(1)
		.min(1)
		.description(`How many facts to keep before dropping the oldest (default ${MAX_FACTS}).`)
		.default(MAX_FACTS),
});

// ---------------------------------------------------------------- model

/**
 * One remembered fact.
 * @typedef {object} Fact
 * @property {string} date - ISO date (YYYY-MM-DD) the fact was learned.
 * @property {string} text - the claim, one sentence.
 */

/**
 * Parse the managed block out of a file body.
 *
 * Tolerant on purpose: a user editing the file by hand can mangle the markers,
 * and a parse failure must never destroy their prose. An unterminated block
 * (marker present, no end marker) is treated as empty, so the first write
 * repairs it instead of appending to garbage.
 * @param {string} body - whole file contents.
 * @returns {Fact[]} facts in file order (oldest first).
 */
export function parseFacts(body) {
	const start = body.indexOf(BEGIN_MARKER);
	if (start < 0) return [];
	const from = start + BEGIN_MARKER.length;
	const end = body.indexOf(END_MARKER, from);
	if (end < 0) return [];
	const block = body.slice(from, end);
	const facts = [];
	for (const line of block.split("\n")) {
		const trimmed = line.trim();
		if (!trimmed.startsWith("- ")) continue;
		// `- 2026-11-20 — the claim`. The em dash is the separator the writer
		// emits; a hand-written `- claim` (no date) is still read, dated empty.
		const match = /^-\s+(\d{4}-\d{2}-\d{2})\s+[—-]\s+(.*)$/.exec(trimmed);
		if (match !== null) {
			facts.push({ date: match[1], text: match[2].trim() });
			continue;
		}
		const bare = /^-\s+(.*)$/.exec(trimmed);
		if (bare !== null && bare[1].trim().length > 0) {
			facts.push({ date: "", text: bare[1].trim() });
		}
	}
	return facts;
}

/**
 * Render one fact line.
 * @param {Fact} fact - the fact.
 * @returns {string} one Markdown list line.
 */
export function formatFact(fact) {
	const date = fact.date.length > 0 ? fact.date : new Date().toISOString().slice(0, 10);
	return `- ${date} — ${fact.text}`;
}

/**
 * Render the managed block (markers included) for a fact list.
 * @param {Fact[]} facts - facts, oldest first.
 * @returns {string} the block, ending with a newline.
 */
export function renderBlock(facts) {
	const lines = [
		BEGIN_MARKER,
		"",
		"## What the assistant has learned about this user",
		"",
		"Written by the `user_profile` tool; the `dsh:user-profile` markers bound the range it owns.",
		"Everything outside them is the user's own text and is never modified. Entries are dated when learned,",
		"so a stale claim is visible as stale — replace or forget it rather than leaving a contradiction.",
		"",
		...(facts.length === 0
			? ["_Nothing recorded yet._"]
			: facts.map((fact) => formatFact(fact))),
		"",
		END_MARKER,
	];
	return `${lines.join("\n")}\n`;
}

/**
 * Replace the managed block in a body, creating or repairing it.
 * @param {string} body - current file contents ('' when absent).
 * @param {string} block - rendered block.
 * @returns {string} new file contents.
 */
export function spliceBlock(body, block) {
	if (body.length === 0) return block;
	const start = body.indexOf(BEGIN_MARKER);
	if (start < 0) {
		// No block yet: append, keeping the user's prose above it untouched.
		const head = body.endsWith("\n") ? body : `${body}\n`;
		return `${head}\n${block}`;
	}
	const end = body.indexOf(END_MARKER, start);
	if (end < 0) {
		// Half-written block (a crash between markers): the block runs to EOF.
		return `${body.slice(0, start)}${block}`;
	}
	const after = end + END_MARKER.length;
	return `${body.slice(0, start)}${block}${body.slice(after).replace(/^\n+/, "\n")}`;
}

/**
 * Apply one edit to a fact list, enforcing the caps.
 *
 * Actions are separate verbs rather than one `write` so the model cannot
 * accidentally reformat the list, and so "I changed my mind" has an explicit
 * `replace` instead of a silent duplicate.
 * @param {Fact[]} facts - current facts, oldest first.
 * @param {{action: string, text?: string, match?: string, date?: string}} input - the requested change.
 * @returns {{facts: Fact[], note: string}} the new list and a message for the model.
 */
export function applyEdit(facts, input) {
	const today = input.date !== undefined && input.date.length > 0
		? input.date
		: new Date().toISOString().slice(0, 10);
	const next = facts.slice();
	switch (input.action) {
		case "add": {
			if (next.some((fact) => fact.text === input.text)) {
				return { facts: next, note: "already recorded; nothing changed" };
			}
			next.push({ date: today, text: input.text });
			break;
		}
		case "replace": {
			const index = next.findIndex((fact) => fact.text.includes(input.match));
			if (index < 0) return { facts: next, note: `no entry containing ${JSON.stringify(input.match)}` };
			next[index] = { date: today, text: input.text };
			break;
		}
		case "forget": {
			const kept = next.filter((fact) => !fact.text.includes(input.match));
			if (kept.length === next.length) {
				return { facts: next, note: `no entry containing ${JSON.stringify(input.match)}` };
			}
			return { facts: kept, note: `forgot ${next.length - kept.length} entr${next.length - kept.length === 1 ? "y" : "ies"}` };
		}
		default:
			throw new HarnessError(`unknown action ${String(input.action)}`, "TOOL_BAD_INPUT");
	}
	let dropped = 0;
	while (next.length > MAX_FACTS) {
		next.shift();
		dropped += 1;
	}
	return {
		facts: next,
		note: dropped === 0 ? "recorded" : `recorded; dropped ${dropped} oldest entr${dropped === 1 ? "y" : "ies"} at the ${MAX_FACTS}-fact cap`,
	};
}

/**
 * Resolve the profile path, refusing anything that escapes the harness home.
 *
 * Absolute names are rejected outright rather than leaning on `join`, which
 * would silently fold `/etc/passwd` into `<home>/etc/passwd` — harmless, but a
 * configuration that looks like it points elsewhere must fail loudly instead of
 * writing somewhere its author did not intend.
 * @param {string} home - resolved harness home.
 * @param {string} fileName - configured relative name.
 * @returns {string} absolute path.
 */
export function profilePath(home, fileName) {
	if (isAbsolute(fileName)) {
		throw new HarnessError(`fileName must be relative to the harness home: ${fileName}`, "TOOL_BAD_INPUT");
	}
	const target = join(home, fileName);
	const normalizedHome = home.endsWith("/") ? home : `${home}/`;
	if (!target.startsWith(normalizedHome)) {
		throw new HarnessError(`fileName must stay inside the harness home: ${fileName}`, "TOOL_BAD_INPUT");
	}
	return target;
}

// ---------------------------------------------------------------- plugin

/**
 * Mount the user_profile tool.
 * @param {import('@deepseek-ai/cordis').Context} ctx - plugin context.
 * @param {ReturnType<typeof Config>} config - row configuration.
 */
function apply(ctx, config) {
	const caps = {
		fileName: config.fileName,
		maxFacts: config.maxFacts,
	};

	// Where the harness home is: read from the process, exactly as
	// dsh-agent-instructions resolves it, so writer and reader agree on the file.
	async function homeDir() {
		const { resolveDshHome } = await import("@deepseek-ai/dsh-home-paths");
		return resolveDshHome();
	}

	async function readBody(target) {
		try {
			return await readFile(target, "utf8");
		} catch (error) {
			if (error && error.code === "ENOENT") return "";
			throw error;
		}
	}

	async function writeBody(target, body) {
		await mkdir(dirname(target), { recursive: true });
		// Stage + rename: a crash mid-write must not leave a half block that the
		// next boot reads as facts. Same atomicity argument as coreutils' mv.
		const staging = `${target}.${randomUUID()}.tmp`;
		await writeFile(staging, body, "utf8");
		await rename(staging, target);
	}

	ctx.tools.register(defineTool({
		name: "user_profile",
		description:
			"Record what you have learned about this user, so a future conversation knows it. " +
			"Entries live in a managed block inside the harness-home AGENTS.md, which every session loads " +
			"before its first request — that file is the only cross-session channel this runtime has. " +
			"Actions: add (one new durable fact), replace (supersede an entry whose text contains `match`), " +
			"forget (drop entries containing `match`), list (read the current entries). " +
			"Add only durable preferences, constraints, or context — not what happened in this conversation, " +
			"which this file cannot hold. One short sentence each; never record credentials or personal identifiers.",
		parameters: {
			action: {
				type: "string",
				required: true,
				description: "add | replace | forget | list",
			},
			text: {
				type: "string",
				description: "add/replace: the fact, one sentence, in the user's own terms.",
			},
			match: {
				type: "string",
				description: "replace/forget: a substring identifying the existing entry to change.",
			},
		},
		timeoutMs: 10000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					ok: { type: "boolean", required: true },
					summary: { type: "string", required: true },
					facts: { type: "array", items: { type: "string" } },
				},
			},
			render: (_args, value) => [{
				type: "text",
				text: [value.summary, ...(value.facts === undefined ? [] : value.facts)].join("\n"),
			}],
		},
		async execute(args) {
			const action = typeof args.action === "string" ? args.action : "";
			const target = profilePath(await homeDir(), caps.fileName);

			if (action === "list") {
				const facts = parseFacts(await readBody(target));
				return {
					ok: true,
					summary: facts.length === 0
						? `no entries yet in ${caps.fileName}`
						: `${facts.length} entr${facts.length === 1 ? "y" : "ies"} in ${caps.fileName}`,
					facts: facts.map((fact) => formatFact(fact)),
				};
			}

			if (action !== "add" && action !== "replace" && action !== "forget") {
				return { ok: false, summary: `unknown action ${JSON.stringify(action)}; use add | replace | forget | list` };
			}
			const text = typeof args.text === "string" ? args.text.trim() : "";
			const match = typeof args.match === "string" ? args.match.trim() : "";
			if ((action === "add" || action === "replace") && text.length === 0) {
				return { ok: false, summary: "text is required for add/replace" };
			}
			if ((action === "replace" || action === "forget") && match.length === 0) {
				return { ok: false, summary: "match is required for replace/forget" };
			}
			if (text.length > MAX_FACT_TEXT) {
				return {
					ok: false,
					summary: `text is ${text.length} characters; keep one fact under ${MAX_FACT_TEXT}`,
				};
			}

			const body = await readBody(target);
			const current = parseFacts(body);
			const outcome = applyEdit(current, { action, text, match });

			let block = renderBlock(outcome.facts);
			if (block.length > MAX_BLOCK_BYTES) {
				// Refuse rather than truncate silently: a profile missing its oldest
				// facts is worse than a clear "forget something first".
				return {
					ok: false,
					summary: `the managed block would exceed ${MAX_BLOCK_BYTES / 1024}KB; forget or replace older entries first`,
				};
			}
			const nextBody = spliceBlock(body, block);
			await writeBody(target, nextBody);

			return {
				ok: true,
				summary: `user_profile: ${outcome.note} → ${caps.fileName} (${outcome.facts.length} entr${outcome.facts.length === 1 ? "y" : "ies"})`,
				facts: outcome.facts.map((fact) => formatFact(fact)),
			};
		},
	}));
}

export { Config, apply, inject, name };